import 'dart:convert';
import 'package:flutter/material.dart';
import 'package:shared_preferences/shared_preferences.dart';
class PremiumAssistantPage extends StatefulWidget { const PremiumAssistantPage({super.key}); @override State<PremiumAssistantPage> createState()=>_PremiumAssistantPageState(); }
class _PremiumAssistantPageState extends State<PremiumAssistantPage>{
 final input=TextEditingController(); final scroll=ScrollController(); List<Map<String,dynamic>> chats=[]; int active=-1; bool busy=false; static const storeKey='assistant_chats_v1';
 @override void initState(){super.initState();load();} @override void dispose(){input.dispose();scroll.dispose();super.dispose();}
 Future<void> load()async{final p=await SharedPreferences.getInstance();try{chats=(jsonDecode(p.getString(storeKey)??'[]') as List).map((e)=>Map<String,dynamic>.from(e)).toList();}catch(_){chats=[];}if(chats.isNotEmpty)active=0;if(mounted)setState((){});}
 Future<void> save()async{final p=await SharedPreferences.getInstance();await p.setString(storeKey,jsonEncode(chats));}
 List<Map<String,dynamic>> get msgs=>active<0?[]:List<Map<String,dynamic>>.from(chats[active]['messages'] as List? ?? []);
 void fresh(){setState((){chats.insert(0,{'title':'محادثة جديدة','messages':[],'updated':DateTime.now().toIso8601String()});active=0;});save();}
 String reply(String q){final s=q.trim().toLowerCase();if(s.contains('سلام')||s=='hi'||s=='hello')return 'وعليكم السلام! أهلاً بيك. تحب نتكلم في إيه؟';if(s.contains('شكرا'))return 'العفو! تحت أمرك.';if(s.contains('اسمك')||s.contains('انت مين'))return 'أنا المساعد الموجود داخل البرنامج. أقدر أساعدك في الشرح والكتابة وتنظيم الأفكار والحسابات، لكن لا أنفّذ أي أوامر أو عمليات داخل البرنامج أو خارجه.';if(s.contains('اكتب')||s.contains('رسالة'))return 'أكيد. ابعتلي الفكرة والجمهور والنبرة اللي تحبها، وأنا أرتب لك النص.';if(s.contains('اشرح')||s.contains('يعني ايه'))return 'تمام. اكتب الموضوع بالتحديد، وهحاول أبسطه لك خطوة بخطوة مع مثال وملخص.';return 'فهمت سؤالك. أنا حالياً محرك محلي خفيف، مش نموذج لغوي ضخم مثل ChatGPT؛ لذلك أقدر أساعد في الشرح والكتابة والأسئلة الشائعة، لكن لا أضمن إجابة دقيقة لكل موضوع متخصص أو معلومة حديثة. وضّح سؤالك أكتر وسأحاول مساعدتك.';}
 Future<void> send([String? suggested])async{final q=(suggested??input.text).trim();if(q.isEmpty||busy)return;if(active<0)fresh();input.clear();setState((){chats[active]['messages']=[...(chats[active]['messages'] as List),{'role':'user','text':q}];if(chats[active]['title']=='محادثة جديدة')chats[active]['title']=q.length>30?q.substring(0,30)+'…':q;busy=true;});await save();await Future<void>.delayed(const Duration(milliseconds:300));if(!mounted)return;setState((){chats[active]['messages']=[...(chats[active]['messages'] as List),{'role':'assistant','text':reply(q)}];busy=false;});await save();WidgetsBinding.instance.addPostFrameCallback((_){if(scroll.hasClients)scroll.jumpTo(scroll.position.maxScrollExtent);});}
 Future<void> delete(int i)async{final ok=await showDialog<bool>(context:context,builder:(c)=>AlertDialog(title:const Text('حذف المحادثة؟'),actions:[TextButton(onPressed:()=>Navigator.pop(c,false),child:const Text('إلغاء')),FilledButton(onPressed:()=>Navigator.pop(c,true),child:const Text('حذف'))]));if(ok==true){setState((){chats.removeAt(i);active=chats.isEmpty?-1:active.clamp(0,chats.length-1);});await save();}}
 Widget history()=>SizedBox(width:250,child:Column(children:[Padding(padding:const EdgeInsets.all(12),child:Row(children:[const Expanded(child:Text('سجل المحادثات',style:TextStyle(fontWeight:FontWeight.bold,fontSize:17))),IconButton(onPressed:fresh,icon:const Icon(Icons.add_comment))])),Expanded(child:ListView.builder(itemCount:chats.length,itemBuilder:(c,i)=>ListTile(selected:i==active,title:Text(chats[i]['title'],maxLines:1,overflow:TextOverflow.ellipsis),onTap:()=>setState(()=>active=i),trailing:IconButton(onPressed:()=>delete(i),icon:const Icon(Icons.delete_outline)))))]));
 @override Widget build(BuildContext context){final wide=MediaQuery.of(context).size.width>850;final chat=Column(children:[Container(padding:const EdgeInsets.all(16),decoration:BoxDecoration(gradient:LinearGradient(colors:[Theme.of(context).colorScheme.primary,Theme.of(context).colorScheme.tertiary]),borderRadius:BorderRadius.circular(20)),child:const Row(children:[Icon(Icons.auto_awesome,color:Colors.white,size:28),SizedBox(width:12),Expanded(child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Text('مساعدك الذكي',style:TextStyle(color:Colors.white,fontSize:20,fontWeight:FontWeight.w900)),Text('محادثة مستقلة وسجل محفوظ محلياً',style:TextStyle(color:Colors.white70,fontSize:12))])),Text('LOCAL',style:TextStyle(color:Colors.white))])),const SizedBox(height:10),Expanded(child:msgs.isEmpty?Center(child:Column(mainAxisSize:MainAxisSize.min,children:[Icon(Icons.forum,size:58,color:Theme.of(context).colorScheme.primary),const SizedBox(height:12),const Text('ابدأ محادثة جديدة',style:TextStyle(fontSize:22,fontWeight:FontWeight.bold)),Wrap(spacing:8,children:['اشرحلي فكرة ببساطة','ساعدني أكتب رسالة','إيه الفرق بين الإيراد والربح؟'].map((s)=>ActionChip(label:Text(s),onPressed:()=>send(s))).toList())])):ListView.builder(controller:scroll,padding:const EdgeInsets.all(8),itemCount:msgs.length+(busy?1:0),itemBuilder:(c,i){if(i>=msgs.length)return const LinearProgressIndicator();final m=msgs[i];final user=m['role']=='user';return Align(alignment:user?Alignment.centerLeft:Alignment.centerRight,child:ConstrainedBox(constraints:BoxConstraints(maxWidth:MediaQuery.of(context).size.width*.78),child:Container(margin:const EdgeInsets.symmetric(vertical:6),padding:const EdgeInsets.all(14),decoration:BoxDecoration(color:user?Theme.of(context).colorScheme.primaryContainer:Theme.of(context).colorScheme.surfaceContainerHighest,borderRadius:BorderRadius.circular(18)),child:SelectableText(m['text'],style:const TextStyle(height:1.5)))));})),Row(children:[Expanded(child:TextField(controller:input,minLines:1,maxLines:5,textInputAction:TextInputAction.send,onSubmitted:(_)=>send(),decoration:const InputDecoration(hintText:'اكتب رسالتك هنا...'))),const SizedBox(width:8),IconButton.filled(onPressed:busy?null:()=>send(),icon:const Icon(Icons.arrow_upward))]),const Text('المساعد لا ينفّذ أوامر. الوضع المحلي لا يملك بحثاً مباشراً بالإنترنت.',style:TextStyle(fontSize:10))]);return Directionality(textDirection:TextDirection.rtl,child:wide?Row(children:[history(),const VerticalDivider(width:1),Expanded(child:Padding(padding:const EdgeInsets.all(14),child:chat))]):Padding(padding:const EdgeInsets.all(12),child:chat));}
}